corporate_design.toad_component_blueprint:
canvas {
  size: 960px 600px;
  fill: #0B0F19;
  font-family: "Space Grotesk, sans-serif";
}

>deepSpace = #0B0F19;
>neuralIndigo = #6366F1;
>synapseCyan = #06B6D4;
>surface = #111827;
>border = #1F2937;
>textWhite = #F8FAFC;
>textMuted = #94A3B8;

rect #brandHeader {
  at: top left of canvas offset 32px 32px;
  size: 896px 48px;
  fill: none;
}

text #logoText {
  at: left center of #brandHeader;
  content: "SYNAPSE // LABS";
  font-size: 18px;
  font-weight: 700;
  color: >textWhite;
}

rect #statusPill {
  at: right center of #brandHeader;
  size: 140px 28px;
  fill: alpha(>synapseCyan, 0.12);
  stroke: >synapseCyan;
  stroke-width: 1px;
  radius: 14px;
}

text #statusLabel {
  at: center of #statusPill;
  content: "CLUSTER READY";
  font-size: 10px;
  font-weight: 700;
  color: >synapseCyan;
}

rect #bentoMain {
  at: below #brandHeader offset 24px;
  size: 580px 420px;
  fill: >surface;
  stroke: >border;
  stroke-width: 1px;
  radius: 12px;
}

text #bentoTitle {
  at: top left of #bentoMain offset 28px 28px;
  content: "NEURAL CORE FABRIC";
  font-size: 24px;
  font-weight: 700;
  color: >textWhite;
}

text #bentoDesc {
  at: below #bentoTitle offset 12px;
  size: 520px;
  content: "High-throughput transformer pipeline with zero memory fragmentation across distributed GPU clusters.";
  font-size: 14px;
  color: >textMuted;
}

rect #bentoSide {
  at: right of #bentoMain offset 20px;
  size: 296px 420px;
  fill: >surface;
  stroke: >border;
  stroke-width: 1px;
  radius: 12px;
}

text #metricNumber {
  at: center of #bentoSide offset 0px -40px;
  content: "99.4 %";
  font-size: 48px;
  font-weight: 700;
  color: >neuralIndigo;
}

text #metricLabel {
  at: below #metricNumber offset 8px;
  content: "INFERENCE EFFICIENCY";
  font-size: 11px;
  font-weight: 600;
  color: >synapseCyan;
}
